<template><PageShell :title="config.title" :subtitle="config.subtitle" :icon="config.icon" eyebrow="Technical Super Admin"><div class="grid gap-4 lg:grid-cols-2"><article v-for="item in cards" :key="item.label" class="rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#071829]"><div class="flex items-start justify-between gap-4"><div><p class="text-sm font-black text-slate-800 dark:text-white/75">{{ item.label }}</p><p class="mt-2 text-xs leading-5 text-slate-400">{{ item.note }}</p></div><span class="rounded-full px-2.5 py-1 text-[.65rem] font-black" :class="item.ok===false?'bg-amber-100 text-amber-700':'bg-emerald-100 text-emerald-700'">{{ item.state }}</span></div></article></div><section v-if="mode==='backups'" class="mt-6 rounded-3xl border border-amber-200 bg-amber-50/70 p-5 dark:border-amber-500/20 dark:bg-amber-500/10"><h2 class="font-black text-amber-900 dark:text-amber-200">Backup tracking is hosting-managed</h2><p class="mt-2 text-sm leading-6 text-amber-800/80 dark:text-amber-200/70">DASCARE does not currently store an automated backup history table. For the thesis build, verify database export/restore and uploaded-file backups at the hosting layer. This page intentionally does not fabricate successful backup timestamps.</p></section></PageShell></template>
<script setup>import{computed,onMounted,ref}from'vue';import{useRoute}from'vue-router';import PageShell from '@/components/management/PageShell.vue';import{fetchTechnicalSummary}from'@/services/adminCompletion';const route=useRoute(),data=ref({health:{},stats:{},service_notes:{}}),mode=computed(()=>route.meta.mode||'health');const configs={health:{title:'Platform Health',subtitle:'Live application, database, session, and storage readiness from the current DASCARE runtime.',icon:'lucide:activity'},services:{title:'Services & APIs',subtitle:'Review the current application service posture and external-service assumptions.',icon:'lucide:server-cog'},security:{title:'Security Center',subtitle:'Monitor account restrictions, throttling signals, and authentication safeguards.',icon:'lucide:shield-check'},backups:{title:'Backup & Recovery',subtitle:'Review recovery readiness without pretending DASCARE already operates a full backup scheduler.',icon:'lucide:database-backup'}};const config=computed(()=>configs[mode.value]||configs.health);const cards=computed(()=>{const h=data.value.health||{},s=data.value.stats||{},n=data.value.service_notes||{};if(mode.value==='services')return[{label:'Application API',state:h.api?'Online':'Unavailable',ok:h.api,note:'PHP endpoint runtime is responding.'},{label:'Database service',state:h.database?'Online':'Unavailable',ok:h.database,note:'PDO connection to the DASCARE database.'},{label:'Email service',state:'Configured',ok:true,note:n.mail||''},{label:'Maps / Geocoding',state:'External',ok:true,note:n.maps||''},{label:'Operational transport',state:'Polling',ok:true,note:n.realtime||''}];if(mode.value==='security')return[{label:'Restricted accounts',state:String(s.restricted_accounts||0),ok:(s.restricted_accounts||0)===0,note:'Suspended or disabled DASCARE accounts.'},{label:'Rate-limit alerts',state:String(s.rate_limit_alerts||0),ok:(s.rate_limit_alerts||0)===0,note:'Current counters with five or more attempts.'},{label:'Audit activity (24h)',state:String(s.audit_24h||0),ok:true,note:'Security and operational changes recorded in audit logs.'},{label:'Session handling',state:h.session?'Active':'Unavailable',ok:h.session,note:'Server-side PHP session state.'}];if(mode.value==='backups')return[{label:'Database connectivity',state:h.database?'Ready':'Unavailable',ok:h.database,note:'Database must be reachable before export or recovery tests.'},{label:'Upload storage',state:h.storage_writable?'Writable':'Review',ok:h.storage_writable,note:'Current media storage path can accept application writes.'},{label:'Automated backup registry',state:'Not tracked',ok:false,note:n.backups||''}];return[{label:'Application API',state:h.api?'Online':'Unavailable',ok:h.api,note:'Current backend runtime status.'},{label:'Database',state:h.database?'Online':'Unavailable',ok:h.database,note:'Current PDO connectivity.'},{label:'Session service',state:h.session?'Online':'Unavailable',ok:h.session,note:'Authentication session runtime.'},{label:'Storage',state:h.storage_writable?'Writable':'Review',ok:h.storage_writable,note:'KYC/emergency media storage write state.'}]});onMounted(async()=>{data.value=await fetchTechnicalSummary()})</script>
